INSERT IGNORE INTO `subcategories` (`category_id`, `name`, `name_en`, `slug`) SELECT c.`id`, 'Конструктори сайтів', 'Website Builders', 'website-builders' FROM `categories` c WHERE c.`slug` = 'development-it' LIMIT 1;
