SET @uid = (SELECT `id` FROM `users` WHERE `email` = 'whitevelvetelf@gmail.com' LIMIT 1);

-- Durable — Конструктори сайтів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'durable.com' OR LOWER(`name`) = LOWER('Durable'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Durable', NULL, 'https://durable.com', NULL, NULL, 'AI-конструктор сайтів для малого бізнесу: створює сайт за 30 секунд, а також дає CRM, онлайн-бронювання, SEO та AI-агентів для блогу й лідів.', 'An AI website builder for small businesses: it creates a site in 30 seconds and also provides a CRM, online booking, SEO and AI agents for blogging and leads.', 'Durable допомагає підприємцям запустити сайт без дизайнера й програміста: досить описати бізнес — і AI за кілька секунд згенерує сайт з текстами й зображеннями, який потім можна редагувати. Окрім сайту, в одному місці є проста CRM, онлайн-бронювання, SEO-налаштування, AI-чат і агенти, що пишуть статті для блогу й допомагають збирати ліди. Власний домен безкоштовний з будь-якою підпискою. Сервісом користуються понад 3 млн компаній. Тарифи: Free — сайт на піддомені, 5 AI-зображень і 10 AI-повідомлень на місяць; Launch — $22 на місяць ($187 на рік); Grow — $41 на місяць ($348 на рік, необмежена команда, щоденні публікації в блозі).', 'Durable helps entrepreneurs launch a website without a designer or developer: describe your business and AI generates a site with text and images in seconds, which you can then edit. Besides the site, it offers a simple CRM, online booking, SEO settings, AI chat and agents that write blog posts and help capture leads, all in one place. A custom domain is free with any subscription. More than 3 million businesses use it. Plans: Free — a site on a subdomain, 5 AI images and 10 AI messages a month; Launch — $22 a month ($187 a year); Grow — $41 a month ($348 a year, unlimited team, daily blog publishing).', 'Сайт з AI за 30 секунд
CRM і онлайн-бронювання
SEO та AI-агенти для блогу й лідів
Безкоштовний власний домен', 'An AI-built site in 30 seconds
CRM and online booking
SEO and AI agents for blog and leads
Free custom domain', 'Малий бізнес, самозайняті й сервісні компанії, яким потрібен сайт швидко й недорого.', 'Small businesses, sole traders and service companies that need a website quickly and affordably.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'durable.com' OR LOWER(`name`) = LOWER('Durable')) ORDER BY `id` LIMIT 1);
