-- Hostinger Website Builder — Конструктори сайтів
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hostinger.com/ai-website-builder' OR LOWER(`name`) = LOWER('Hostinger Website Builder'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Hostinger Website Builder', NULL, 'https://www.hostinger.com/ai-website-builder', NULL, NULL, 'AI-конструктор сайтів від Hostinger з хостингом, доменом і поштою: AI генерує сайт за описом, а агентний режим будує інтернет-магазини й застосунки в діалозі.', 'Hostinger''s AI website builder with hosting, a domain and email: AI generates a site from a description, and agentic mode builds stores and apps through conversation.', 'Конструктор сайтів Hostinger поєднує AI-генерацію з хостингом. У звичайному режимі AI миттєво створює сайт за вашим описом, і його можна доопрацювати перетягуванням блоків; агентний режим («vibe coding») дає змогу в діалозі будувати складніші проєкти — інтернет-магазини, сайти з підпискою, інтерактивні застосунки. До пакета входять хостинг, SSL, безкоштовний домен на перший рік (на довгих тарифах), поштові скриньки, понад 400 шаблонів, SEO-інструменти й AI для текстів, а продаж в інтернет-магазині без комісії. Акційні ціни при оплаті на 48 місяців: Premium — $2,99 на місяць (до 3 сайтів); Unlimited — $3,99 (необмежені сайти); Cloud Startup — $7,99 на місяць.', 'Hostinger''s website builder combines AI generation with hosting. In standard mode AI instantly creates a site from your description, which you can refine with drag-and-drop; agentic mode (''vibe coding'') lets you build more complex projects — online stores, membership sites and interactive apps — through conversation. The package includes hosting, SSL, a free domain for the first year (on longer plans), email mailboxes, 400+ templates, SEO tools and AI writing, with 0% transaction fees for online stores. Promotional prices on 48-month plans: Premium — $2.99 a month (up to 3 sites); Unlimited — $3.99 (unlimited sites); Cloud Startup — $7.99 a month.', 'Сайт з AI за описом
Агентний режим для магазинів і застосунків
Хостинг, SSL, домен і пошта в пакеті
400+ шаблонів і SEO-інструменти', 'AI site from a description
Agentic mode for stores and apps
Hosting, SSL, domain and email included
400+ templates and SEO tools', 'Підприємці, блогери й малий бізнес, які хочуть сайт разом із хостингом за низьку ціну.', 'Entrepreneurs, bloggers and small businesses that want a site with hosting at a low price.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
