SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'squarespace.com' OR LOWER(`name`) = LOWER('Squarespace'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Squarespace', NULL, 'https://www.squarespace.com', NULL, NULL, 'Конструктор сайтів і інтернет-магазинів з дизайнерськими шаблонами та AI-інструментами для створення сайту й текстів; 14 днів безкоштовно.', 'A website and online store builder with designer templates and AI tools for building the site and writing copy; 14-day free trial.', 'Squarespace відомий охайними дизайнерськими шаблонами та простим редактором перетягування. AI допомагає швидко зібрати сайт і писати тексти, а платформа охоплює інтернет-магазин, членства, бронювання, блог і маркетингові інструменти. Сайти адаптовані під мобільні, трафік необмежений, підтримка працює цілодобово, а на річних тарифах домен перший рік безкоштовний. Тарифи (при річній оплаті / помісячно): Basic — $12 / $19 (комісія 2% з продажів, 10 разових AI-кредитів); Core — $17 / $27 (без комісії, 20 AI-кредитів на місяць, пошта Google Workspace на перший рік); Advanced — $25 / $36 (найнижчі комісії платежів, 120 AI-кредитів на місяць). Кожен сайт починається з 14-денного пробного періоду.', 'Squarespace is known for polished designer templates and a simple drag-and-drop editor. AI helps you assemble a site quickly and write copy, and the platform covers online stores, memberships, bookings, blogging and marketing tools. Sites are mobile-optimised, bandwidth is unlimited, support is 24/7, and annual plans include a free domain for the first year. Plans (billed annually / monthly): Basic — $12 / $19 (2% transaction fee, 10 one-time AI credits); Core — $17 / $27 (0% transaction fee, 20 AI credits a month, Google Workspace email for the first year); Advanced — $25 / $36 (lowest payment processing fees, 120 AI credits a month). Every site starts with a 14-day free trial.', 'Дизайнерські шаблони й редактор перетягування
AI для створення сайту й текстів
Інтернет-магазин, членства, бронювання
Безкоштовний домен на рік (річні тарифи)', 'Designer templates and drag-and-drop editor
AI for building the site and writing copy
Online store, memberships, bookings
Free domain for a year (annual plans)', 'Креативні фахівці, малий бізнес і інтернет-магазини, яким важливий вигляд сайту.', 'Creatives, small businesses and online stores that care about how their site looks.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
