-- Jira — Управління проєктами
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'atlassian.com/software/jira' OR LOWER(`name`) = LOWER('Jira'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Jira', NULL, 'https://www.atlassian.com/software/jira', NULL, NULL, 'Система управління проєктами й задачами від Atlassian з AI Rovo: пошук, чат і агенти, що розуміють вашу роботу, плюс автоматизації.', 'Atlassian''s project and work management system with Rovo AI: search, chat and agents that understand your work, plus automations.', 'Jira — один із найпоширеніших інструментів для планування й відстеження роботи команд, від розробки ПЗ до маркетингу та операцій. Задачі ведуться на дошках, у списках, таймлайнах і спринтах, а автоматизації беруть на себе рутинні дії. У всі платні тарифи вбудовано Atlassian Rovo — AI-пошук, чат і агентів, які розуміють контекст ваших проєктів, а також AI-функції в самих задачах. Тарифи за користувача на місяць: Free — до невеликої команди безкоштовно; Standard — $7,91 (400 кроків автоматизації, 25 кредитів Rovo); Premium — $14,54 (750 кроків, 70 кредитів Rovo); Enterprise — за запитом.', 'Jira is one of the most widely used tools for planning and tracking team work, from software development to marketing and operations. Work is managed on boards, lists, timelines and sprints, and automations take care of routine actions. All paid plans include Atlassian Rovo — AI search, chat and agents that understand the context of your projects — plus AI features inside work items. Plans per user a month: Free — free for small teams; Standard — $7.91 (400 automation steps, 25 Rovo credits); Premium — $14.54 (750 automation steps, 70 Rovo credits); Enterprise on request.', 'Дошки, списки, таймлайни й спринти
AI Rovo: пошук, чат і агенти
Автоматизації рутинних дій
Інтеграції з екосистемою Atlassian', 'Boards, lists, timelines and sprints
Rovo AI: search, chat and agents
Automation of routine actions
Atlassian ecosystem integrations', 'Команди розробки, продукту, маркетингу й операцій у компаніях будь-якого розміру.', 'Software, product, marketing and operations teams at companies of any size.', 'web,mobile,desktop', 'none', 'published', 0, 'found', @uid, '2026-10-01 00:00:00' FROM DUAL WHERE @new = 1;
